// TNi process confirmed by Chris Taylor, September 2026.
// Examples are fictional; no customer records or source workbooks are published.
export const COURSE_VERSION = '1.1.0';
const q=(id,prompt,options,explanation)=>({id,prompt,options,correct:0,explanation});
const section=(title,paragraphs,steps=[])=>({title,paragraphs,steps});
export const modules = [
 {
  id:'handoff',title:'Take ownership of the project',phase:'Define',subtitle:'PO acknowledgement, scope, and internal kickoff',
  objectives:['Identify when TNi PM ownership begins.','Connect the quote, scope of supply, and cost detail.','Prepare the right people for the internal handoff.'],
  foundation:'Scope describes what TNi has agreed to supply. A budget describes the planned resources and cost. A schedule places the work and decisions in time. These three controls need to agree; a low cost or a fast schedule is not success if the delivered machine misses the agreed requirements.',
  sections:[
   section('Start after PO acknowledgement',['TNi PM ownership starts after purchase order acknowledgement. The first task is to understand the commitment TNi has made and bring the delivery team together. The quote and PO establish the context for equipment requirements, scope, delivery, payment milestones, training and warranty terms.','The internal meeting includes the PM, operations, controls, mechanical design, machine shop and build managers. Each function needs to understand its part of the same job.']),
   section('Review the scope and the estimate together',['Review the quoted requirements and scope of supply alongside the cost-detail spreadsheet. The spreadsheet contains mechanical and controls design, make and purchased items, equipment, labor hours and outsourced work. The final project budget is targeted from this cost detail.','A planned purchase and an item TNi will manufacture need different activities, but both must be reflected in the budget and schedule. Do not treat the sales price as the available spending budget.']),
   section('Turn the handoff into usable project controls',['For training practice, organize the handoff into the following review sequence. These prompts support the agreed TNi meeting; they are not a new approval form or a new budget authority.'],['Identify the agreed equipment requirements and scope of supply.','Review departmental labor, purchases, make items and outside services in the cost detail.','Identify the promised shipment date, quoted lead times and required design decisions.','Identify the payment milestones and customer-provided information or parts.','Carry unresolved requirements into the project open-items process.'])
  ],
  takeaway:'The PM starts with the agreed scope and the cost-detail plan, with all delivery functions involved in the internal handoff.',
  scenario:{prompt:'The quote includes an outsourced operation, but the build team assumes that operation will be completed internally. What should the PM do at kickoff?',answer:'Bring the quote and cost detail into the discussion with the relevant managers. Clarify the agreed scope and the planned outside work so the labor, purchasing and schedule assumptions agree. Resolve the mismatch before treating the internal-build assumption as the plan.'},
  quiz:[q('h1','When does TNi PM ownership begin?',['After PO acknowledgement','When the customer first requests a quote','Only after mechanical design approval','At the first customer runoff'],'PM ownership begins after PO acknowledgement.'),q('h2','Which group belongs in the internal handoff?',['PM, operations, controls, mechanical design, machine shop and build managers','PM and the customer only','Accounting and sales only','Build manager and trucking provider only'],'All named internal delivery functions participate in the handoff.'),q('h3','What establishes the target for the final project budget?',['The cost-detail spreadsheet','The customer’s sales price alone','The final invoice','The PM’s previous project total'],'The final budget is targeted from the job’s cost detail.'),q('h4','What should the team review together?',['Quoted requirements, scope of supply and cost detail','Only the ship date','Only mechanical drawings','Only the customer contact list'],'Scope and cost assumptions must be understood together.'),q('h5','The cost sheet includes outside services. What is the right treatment?',['Include that work in the handoff and project plan','Ignore it because TNi is not performing it','Automatically replace it with internal labor','Treat it as a customer scope change immediately'],'Outside services are part of the planned delivery work; a mismatch needs review, not an automatic scope change.'),
   q("h6","The selling price is higher than the estimated cost. Which amount should guide the PM’s spending plan?",["The planned resources and costs in the cost-detail spreadsheet", "The full selling price as the available spending budget", "The selling price less payments already received", "Only purchase costs, with labor tracked outside the budget"],"The cost-detail spreadsheet establishes the project cost plan. The sales price is not the available spending budget."),
   q("h7","A requirement remains unclear after the kickoff review. What should happen next?",["Carry it into the project open-items process for resolution", "Let each department use its own interpretation", "Remove it from the scope until the customer asks again", "Wait until customer runoff to discuss it"],"Unresolved requirements belong in the project open-items process so they remain visible and can be resolved."),
   q("h8","The quote assumes an outside operation, but build plans to perform it internally. What is the PM’s next step?",["Review the quote and cost detail with the relevant managers to reconcile the plan", "Accept the build assumption without checking the estimate", "Treat the mismatch as an approved customer scope change", "Keep both plans and decide after the work begins"],"The PM brings the scope and estimate into the handoff discussion so labor, purchasing and schedule assumptions agree."),
   q("h9","Which customer dependencies should the PM identify during the handoff?",["Customer-provided information or parts needed to complete the project", "Only the customer’s preferred meeting time", "Only information needed after warranty expiration", "Only items that have already caused a delay"],"The handoff identifies required customer information and parts early enough to include them in the project plan."),
   q("h10","A project meets its cost and shipment targets but misses an agreed equipment requirement. How should the PM assess it?",["The scope, budget and schedule must all be satisfied; the missed requirement still needs resolution", "Meeting cost and shipment targets makes the project successful", "The requirement can be removed because the budget is spent", "The requirement automatically becomes paid change work"],"Scope, budget and schedule need to agree. A favorable cost or date does not compensate for missing the agreed requirements.")]
 },
 {
  id:'planning',title:'Build a delivery plan',phase:'Define',subtitle:'Plan backward from shipment and release purchases correctly',
  objectives:['Use the correct promised-delivery milestone.','Build dependencies backward from shipment.','Apply design approval rules to long-lead purchasing.'],
  foundation:'A milestone is an important event, such as approval or shipment. A dependency means one activity needs an output from another. Working backward exposes the latest dates those outputs are needed. Quoted supplier lead time is an input to the plan; it does not remove the need for an approved design.',
  sections:[
   section('Anchor the plan to shipment',['At TNi, the promised delivery end date means shipping from TNi. It does not mean arrival at the customer or final acceptance. The PM starts with that promised ship date and works backward.','The overall sequence runs through mechanical design and approval, controls design and approval, build and testing at TNi, customer runoff at TNi, teardown and shipping, customer-site reassembly and testing, then final runoff and acceptance. Payment milestones are also included on the project plan.']),
   section('Use actual quoted lead times',['Populate long-lead items using their suppliers’ quoted delivery times. Connect those delivery periods to the design decisions and assembly activities that depend on them. An item that arrives after it is needed creates a scheduling problem even if its purchase price is within budget.','The normal long-lead release follows a customer design concept review. Long-lead items are not ordered without design approval. Do not equate the normal concept-review release with waiting for every detailed drawing in the whole project.']),
   section('Handle early release as an engineered exception',['An example exception is a robot whose reach and payload capacity have already been engineered. The TNi design manager authorizes the early release to the PM. The PM does not independently waive the design requirement because an item has a long delivery time.'],['Establish the shipment commitment.','Work backward through runoff, testing, build, deliveries and design decisions.','Use quoted supplier lead times.','Confirm the appropriate design approval before placing long-lead orders.','Include payment milestones and the work after shipment in the project plan.'])
  ],
  takeaway:'Shipment from TNi is the delivery anchor. Long lead time is a reason to plan early, not permission to buy an unapproved item.',
  scenario:{prompt:'A robot supplier quotes 18 weeks. The full machine design is unfinished, but reach and payload have been engineered. Can the PM order it immediately?',answer:'The engineered reach and payload may support an early-release exception. The TNi design manager must authorize that release to the PM. The quoted 18-week lead time alone is not authorization.'},
  quiz:[q('p1','What does TNi’s promised delivery end date mean?',['Shipment from TNi','Arrival at the customer','Final customer acceptance','Warranty expiration'],'Use shipment from TNi as the schedule anchor.'),q('p2','What should populate supplier lead times?',['Suppliers’ quoted delivery times','A fixed four-week allowance for all items','The previous project’s dates without checking','The final invoice dates'],'The quoted delivery times populate the long-lead plan.'),q('p3','When are normal long-lead orders released?',['After the customer design concept review and appropriate design approval','As soon as the customer asks for a quote','Whenever the PM sees a favorable price','Only after onsite acceptance'],'Normal release follows concept review and design approval.'),q('p4','Who authorizes a qualifying early release to the PM?',['The TNi design manager','The supplier','The trucking company','The PM acting alone'],'The design manager authorizes the engineered exception to the PM.'),q('p5','Which additional milestones belong in the project plan?',['Payment milestones','Only internal manufacturing operations','Only customer meetings','Only warranty calls'],'The PM tracks payment milestones on the plan and initiates invoicing when applicable.'),
   q("p6","After identifying the promised shipment date, how should the PM develop the plan?",["Work backward through runoff, testing, build, deliveries and design decisions", "Schedule design independently and add shipment at the end", "Use supplier delivery dates as the only project milestones", "Start with final customer acceptance and label it the shipment date"],"Working backward from shipment exposes the dates required for the activities and decisions that support that commitment."),
   q("p7","An approved purchased item will arrive after assembly needs it, but its price is within budget. What does this indicate?",["A schedule dependency problem that still needs attention", "No problem because purchasing stayed within budget", "Automatic permission to skip the affected assembly work", "A change to the definition of the promised delivery date"],"On-budget purchasing does not eliminate a schedule problem. The delivery must support the activity depending on it."),
   q("p8","A robot has a long quoted lead time, but its reach and payload have not been engineered. What is the appropriate response?",["Resolve the engineering and approval needs; lead time alone does not authorize an order", "Order immediately because a long lead time overrides approval", "Use the previous job’s robot without checking this application", "Ask the supplier to act as TNi’s design approval authority"],"The engineered early-release exception depends on the design basis and design-manager authorization. Lead time alone is insufficient."),
   q("p9","An approved long-lead item has completed the appropriate concept review. Must every detailed drawing for the entire project also be finished before normal release?",["No; confirm the appropriate approval for the item without imposing a whole-project drawing requirement", "Yes; concept review can never support long-lead release", "No; concept review eliminates approval requirements for every other item", "Yes; purchases must wait until the machine is assembled"],"Normal release follows concept review and the appropriate design approval, not necessarily completion of every project detail drawing."),
   q("p10","Should the project plan stop when the machine ships from TNi?",["No; it must also address customer-site reassembly, testing, runoff and acceptance", "Yes; shipment completes all PM responsibilities", "Yes; onsite activities belong only in the warranty record", "No; replace the shipment commitment with the final acceptance date"],"Shipment is the promised-delivery anchor, while the overall project plan also includes the work after shipment.")]
 },
 {
  id:'design',title:'Mechanical and controls approvals',phase:'Define',subtitle:'Customer acceptance, agreed markups and records for both disciplines',
  objectives:['Apply the customer approval process to both mechanical and controls design.','Retain approval evidence and agreed markups for each discipline under the job number.','Distinguish agreed markups from a new scope request.'],
  foundation:'Mechanical design approval and controls design approval are both part of the project. An approval record makes each decision traceable. A markup identifies a change or clarification on reviewed material. The PM needs to know what the customer accepted for each discipline, while the responsible engineers need a clear basis on which to proceed. A new request outside the agreed scope belongs in change control.',
  sections:[
   section('Obtain mechanical and controls approvals',['Obtain customer acceptance for both the mechanical design and the controls design. For each, the customer provides either a signed acceptance with markups or an email documenting the same acceptance and agreed markups. Preserve the evidence of each decision.','Mechanical design and approval lead to controls design and approval in the project sequence. Track both approvals in the plan; mechanical acceptance does not by itself approve the controls design. The design concept review also supports approved long-lead purchasing.']),
   section('Keep both approval records with the job',['Retain the mechanical and controls approval evidence in the project file folder on TNi’s server drive under the TNi job number, for example 42175. This course uses that number only as an illustration of the folder convention.','Make clear which design each acceptance covers and retain its agreed markups. When reviewing status, connect the mechanical approval to mechanical engineering work and the controls approval to controls engineering work.']),
   section('Proceed from each discipline’s agreed markups',['Mechanical and controls engineering each incorporate the markups agreed for their design and proceed without another formal customer approval cycle for those markups. This does not remove the requirement to obtain the initial customer approval for both disciplines.','If the customer introduces a new scope request in either discipline, the PM works through the OCR process with engineering. Approval of an existing markup is not a blanket approval for unrelated additional work.'],['Confirm customer acceptance and agreed markups for both mechanical and controls design.','Retain each signed acceptance or equivalent email in the job folder.','Use the respective agreed markups as mechanical and controls engineering’s basis to proceed.','Route new customer scope requests in either discipline into the OCR process.'])
  ],
  takeaway:'Obtain and retain both mechanical and controls approvals. Each engineering discipline then proceeds from its agreed markups without another formal approval cycle for those markups.',
  scenario:{prompt:'The customer has approved the mechanical design and later emails acceptance of the controls design with three agreed markups. Controls engineering incorporates them. A team member proposes waiting for another signed controls approval before continuing. What should the PM explain?',answer:'Retain both the mechanical approval and the controls acceptance email with its agreed markups under the job number. The email is acceptable controls approval evidence. Controls engineering proceeds from those markups without another formal approval; a new scope request would go through OCR. The earlier mechanical approval alone would not have approved the controls design.'},
  quiz:[q('d1','Which is an acceptable customer approval record for mechanical or controls design?',['A signed acceptance with markups or an equivalent email','An undocumented phone conversation only','A supplier’s order acknowledgement','An internal estimate with no customer response'],'The signed record or equivalent email documents customer acceptance and agreed markups for the respective design. This applies to both mechanical and controls approvals.'),q('d2','Where are mechanical and controls approval records retained?',['In the server project folder under the TNi job number','Only in the PM’s memory','Only in the supplier’s system','In the customer-only PDF with no retained source'],'Retain the approval evidence and agreed markups for both disciplines in the job-number folder.'),q('d3','After customer approval and incorporation of the agreed mechanical or controls markups, what happens?',['Engineering proceeds without another formal customer approval','Every drawing must restart the approval process','All long-lead orders must be cancelled','The budget is automatically increased'],'The responsible engineering discipline proceeds from its agreed markups without another formal approval cycle for those markups. Both mechanical and controls design still require their initial customer approval.'),q('d4','The customer adds a mechanical or controls requirement outside the agreed scope. What applies?',['TNi’s OCR process','Automatic inclusion in the original budget','No documentation if the work is small','The warranty process'],'A new customer scope request in either mechanical or controls design triggers OCR.'),q('d5','What makes a mechanical or controls approval record useful?',['It documents acceptance and the agreed markups','It contains only a meeting date','It replaces all technical requirements','It authorizes all future changes'],'The record preserves what the customer accepted and the agreed markups for the design it covers. Keep evidence for both mechanical and controls approvals.'),
   q("d6","The customer has approved the mechanical design. What is the status of controls approval?",["Controls design still requires its own customer acceptance", "Mechanical acceptance automatically approves the controls design", "Controls approval can be replaced by the supplier’s acknowledgement", "Controls approval is unnecessary if the schedule includes controls work"],"Both mechanical and controls approvals are required. Mechanical acceptance alone does not approve controls design."),
   q("d7","Which approvals should be visible in the project plan?",["Both mechanical design approval and controls design approval", "Mechanical approval only, with controls assumed complete", "Controls approval only, because it follows mechanical work", "Only final runoff approval, replacing both design approvals"],"Track both design approvals at their respective points in the project sequence."),
   q("d8","Controls engineering receives an acceptance email with agreed markups. What should the PM retain with it?",["A clear record of which controls design was accepted and the agreed markups", "Only the meeting date, without the acceptance or markups", "Only the mechanical approval because it came first", "Only the supplier quote for the controls components"],"Approval evidence must identify what the customer accepted and preserve the markups for the respective design."),
   q("d9","A controls engineer incorporates the customer’s already agreed markups. What does the no-repeat-approval rule mean?",["No further formal approval cycle is needed for those markups after the initial controls acceptance", "The initial controls approval can also be skipped", "Mechanical approval can replace the initial controls acceptance", "Any later customer controls request is already authorized"],"Proceeding from agreed markups does not remove the requirement to obtain the initial approval for each discipline."),
   q("d10","How should the PM relate retained design approvals to engineering progress?",["Connect each discipline’s work to its own recorded acceptance and agreed markups", "Use whichever approval email is most recent for both disciplines", "Treat any job-folder document as approval of all design work", "Track approval dates without checking what was accepted"],"Mechanical and controls records should each provide a clear basis for the corresponding engineering work.")]
 },
 {
  id:'communication',title:'Keep the project visible',phase:'Execute',subtitle:'Customer updates, open items and internal status reviews',
  objectives:['Separate meeting frequency from document frequency.','Send the correct customer-facing PDF reports.','Present schedule issues for internal management review.'],
  foundation:'A schedule communicates when work and decisions are needed. An open-items list communicates unresolved actions. A status discussion explains what changed, what is blocked and what decision is needed. These tools work together; distributing a schedule alone does not resolve a roadblock.',
  sections:[
   section('Maintain a predictable customer rhythm',['Each PM conducts weekly or biweekly customer meetings. The discussion covers the project schedule, open items, status and new items. Customer-caused schedule impacts, such as late information, are discussed in those meetings and then added to the open-items list.','Regardless of whether a meeting occurs that week, the schedule and customer open-items report are sent weekly. A biweekly meeting does not mean a biweekly document update.']),
   section('Publish the right view',['The schedule is maintained in Microsoft Project and sent as a PDF. The open-items list is maintained in Excel. Sort or display only the customer items, then send that customer view as a PDF. The working Excel file is not the specified customer distribution format.','The reference action list has fields for the item, dates, responsible person, status and notes, with visibility fields. The course teaches the customer-only view and PDF workflow; it does not depend on workbook macros.']),
   section('Present internal status each week',['TNi holds a weekly status meeting for all jobs. The general manager, operations manager, mechanical design, controls design, machine shop and build managers participate. The PM presents project status, including schedule adherence and roadblocks, and the group discusses management intervention.','Budget concerns may arise there, but the usual path is for the PM to address a recognized budget concern directly with the general manager. A threatened milestone is raised with the operations manager rather than held for the next routine meeting.'])
  ],
  takeaway:'Meetings may be biweekly; customer schedule and open-items PDFs are still weekly.',
  scenario:{prompt:'The customer meets with TNi every other Tuesday. There is no meeting this week, and the internal Excel list contains shop-only actions. What does the PM send?',answer:'Send the current Microsoft Project schedule as a PDF and a PDF of the Excel open-items view displaying only customer items. Continue the weekly document rhythm even though no meeting is scheduled.'},
  quiz:[q('c1','How often are the two customer reports sent?',['Weekly','Only when a customer meeting occurs','Only when a milestone slips','Monthly'],'Both reports are sent weekly, even with biweekly meetings.'),q('c2','What format is the customer schedule?',['PDF exported from Microsoft Project','The working Excel file','A screenshot of SAGE','A verbal summary only'],'The schedule is maintained in Microsoft Project and distributed as PDF.'),q('c3','How is the open-items report prepared?',['Export the open-items Excel list as a PDF and send it to the customer','Send the entire working workbook','Include every shop-only item','Replace the list with the invoice'],'The open-items Excel list is exported as a PDF and sent to the customer.'),q('c4','Where are customer-caused schedule impacts addressed?',['In customer meetings, then on the open-items list','Only after final acceptance','Only in an unshared personal note','They are excluded from project status'],'Discuss the impacts and add them to open items.'),q('c5','Who presents a project at TNi’s weekly internal status meeting?',['The PM','Only the accountant','Only the customer','Only the supplier'],'The PM presents schedule status and roadblocks for management review.'),
   q("c6","The customer meets with TNi every other week. What should be sent during the week with no meeting?",["The weekly schedule PDF and open-items PDF", "Nothing until the next customer meeting", "Only an informal verbal status update", "The working Excel file instead of the PDF report"],"The reports are sent weekly regardless of whether customer meetings are weekly or biweekly."),
   q("c7","Which topics belong in the regular customer project discussion?",["The schedule, open items, status and new items", "Only the schedule dates that remain unchanged", "Only completed items, with new issues held for closeout", "Only invoice dates, with technical actions omitted"],"The customer discussion covers schedule, open items, current status and new items so decisions and actions remain visible."),
   q("c8","The working action list contains internal and customer items. What should the PM do before exporting the customer report?",["Sort or display the customer items and export that view as a PDF", "Send the entire working workbook without reviewing visibility", "Delete all internal items from the working list", "Send only a screenshot of the first page regardless of the remaining items"],"The lesson calls for a customer view exported to PDF while the working list remains in Excel."),
   q("c9","What should the PM emphasize at TNi’s weekly internal status meeting?",["Schedule adherence, roadblocks and any management intervention needed", "Only items that are already complete", "Only the latest customer payment, without delivery status", "A list of meetings held instead of project status"],"The PM presents status and obstacles so the delivery managers can discuss intervention where needed."),
   q("c10","A known milestone threat arises before the next internal status meeting. What should the PM do?",["Raise it with the operations manager promptly", "Wait for the weekly meeting before mentioning it", "Send the schedule PDF and assume that resolves the threat", "Change the customer commitment without internal review"],"The weekly meeting is not a reason to delay escalation of a threatened milestone to operations.")]
 },
 {
  id:'budget',title:'Monitor costs and labor',phase:'Execute',subtitle:'Compare SAGE actuals with the cost-detail plan',
  objectives:['Use weekly and as-needed job reports.','Compare hours and costs in corresponding categories.','Recognize and escalate a budget concern.'],
  foundation:'An actual is a cost or labor entry already recorded. A commitment, such as an open purchase order, is an obligation that may not yet be posted as an actual. Comparing actuals with the plan requires matching categories and reporting dates. Do not add the same purchase twice when a commitment becomes an actual.',
  sections:[
   section('Use the job’s plan as the reference',['TNi uses SAGE ERP. The PM requests job reports weekly and may request additional reports as needed. The reports cover expenses, labor, open POs and committed costs. The required practice is to compare actual spending and labor with the plan based on the cost-detail spreadsheet.','SAGE uses corresponding categories for the comparison. Review both labor hours and money: a material saving does not explain why a design-hours allowance has been consumed. The purpose is to identify differences early enough to act.']),
   section('Understand the cost-detail structure',['Mechanical planning includes design, assembly, welding and machining hours, material and purchased-item categories, and miscellaneous outside services. Controls planning includes panel build, machine wiring, pneumatic, lubrication, coolant and hydraulic work, with design hours and component costs.','The summary also provides for supporting work such as rigging, manuals, mechanical and controls startup, painting, guarding, machine runoff, skidding and shipping, and installation. The mechanical detail sheets contain Actual Cost, Difference From Quote, Purchase Order Number and Remarks fields. No customer cost amounts are included in this course.']),
   section('Make the comparison useful',['Compare the same category in SAGE and the cost-detail plan. Check what has been posted, what remains committed, and what work has been completed. A positive remaining dollar amount by itself is not proof that the remaining work is funded.','When the PM recognizes a budget concern, the normal escalation is directly to the general manager. The course does not introduce a separate formal cost-at-completion procedure as an existing TNi requirement. OCR work keeps its own job number and accounting; the original project budget stays unchanged.'],['Request the current job report.','Match labor and spending categories to the cost-detail plan.','Review variances alongside commitments and project status.','Address recognized budget concerns with the general manager.'])
  ],
  takeaway:'Use the cost detail as the plan, SAGE as the actual/commitment source, and the general manager as the normal escalation for budget concerns.',
  scenario:{prompt:'Illustrative figures: mechanical design was planned at 200 hours. SAGE shows 180 hours used, but substantial design work remains. Purchased materials are under their allowance. Is there still a concern?',answer:'Yes. Only 20 planned design hours remain, and the remaining work may require more. Review the labor category against the actual work status and address the concern with the general manager. A materials saving does not remove the need to understand the design-hours variance.'},
  quiz:[q('b1','How often does the PM obtain SAGE job reports?',['Weekly and additionally as needed','Only at final invoice','Only when requested by a supplier','Once at kickoff'],'Weekly review is the normal rhythm, with additional reports as needed.'),q('b2','What is the basis for actual-versus-plan comparison?',['The cost-detail spreadsheet','The customer’s total PO value alone','A generic industry margin','The last project’s final cost'],'The cost-detail plan is the comparison basis.'),q('b3','Who normally receives recognized budget concerns?',['The general manager','The trucking provider','The customer’s maintenance technician','No one until closeout'],'The PM normally addresses budget concerns directly with the general manager.'),q('b4','A purchase has moved from an open commitment to a posted actual. What should the PM avoid?',['Counting the same cost twice','Reviewing its PO number','Checking its job allocation','Comparing it to the plan'],'Actuals and open commitments need to be understood so the same purchase is not duplicated.'),q('b5','What happens to the original budget when OCR work is approved?',['It remains unchanged; OCR work has separate accounting','It is overwritten with the OCR total','It is replaced by the sales price','It is no longer monitored'],'OCR work has a separate job number and accounting; original-budget monitoring continues.'),
   q("b6","What is a committed cost in the context of the job review?",["An obligation such as an open PO that may not yet be posted as an actual", "Only labor hours already charged to the job", "Money that is automatically available for additional work", "A customer’s sales price before discounts"],"Commitments represent obligations that may not yet appear as posted actual spending."),
   q("b7","SAGE shows unused material budget, but design hours are nearly consumed with substantial work left. What should the PM do?",["Review the labor variance against the corresponding plan and address the concern", "Assume the material balance proves all remaining labor is funded", "Stop reviewing hours and compare total dollars only", "Transfer the concern into an OCR without a customer scope request"],"Labor hours and money both need review in corresponding categories; a material saving does not explain excessive design hours."),
   q("b8","How should SAGE results be aligned with the cost-detail plan?",["Compare corresponding categories and reporting dates, including remaining commitments", "Compare any two totals even if the categories and dates differ", "Exclude open POs until every invoice is posted", "Compare actual spending only with the selling price"],"A useful comparison aligns categories and reporting dates and considers both posted actuals and outstanding commitments."),
   q("b9","A report shows a positive budget balance. What additional information is needed to judge whether the job remains adequately funded?",["Remaining work, commitments and what has already been posted", "Only the original selling price", "Only whether last week’s report also showed a positive balance", "Only the amount of customer payments received"],"A positive balance by itself does not establish that the remaining work and obligations are covered."),
   q("b10","Which supporting activities also need recognition in the cost-detail plan?",["Work such as rigging, manuals, startup, runoff, skidding, shipping and installation", "Only direct machining and purchased components", "Only activities performed before design approval", "Only activities listed on supplier invoices"],"The cost-detail summary includes supporting delivery work as well as mechanical and controls design, build and components.")]
 },
 {
  id:'changes',title:'Manage customer scope changes',phase:'Execute',subtitle:'Use OCR without losing the original project baseline',
  objectives:['Recognize a customer scope-change trigger.','Apply the written-agreement and separate-PO process.','Keep OCR cost and schedule treatment distinct.'],
  foundation:'Change control makes added work and its consequences visible. Cost and schedule do not have to be recorded in the same way: TNi accounts for an OCR separately while updating project dates when the approved change adds schedule days. An internal overrun alone is not automatically a customer scope change.',
  sections:[
   section('Quote the requested change',['A customer scope-change request triggers TNi’s Order Change Request process. The PM works with engineering to define and quote the change, then issues the quote on TNi’s OCR form.','Work through what the customer is requesting and its effect on the agreed supply. The quote is prepared with engineering; the PM should not silently treat additional work as part of the original quoted scope.']),
   section('Obtain the agreement and pursue the PO',['TNi expects the customer to issue a separate PO for the OCR. Written customer agreement is generally sufficient for TNi to proceed before that separate PO arrives.','Keep those two facts distinct. The expected separate PO is still part of the commercial process, while TNi generally allows work to proceed on written agreement. Do not substitute an undocumented verbal understanding for the written agreement.']),
   section('Preserve the original budget; update affected dates',['The original project budget is not revised for OCR work. Each OCR uses a separate job number and separate accounting. That preserves visibility into original-scope spending and change work.','Project dates are revised if the approved change creates additional days in the schedule. A cost change does not automatically create a schedule extension; consider whether the work actually adds days. Communicate the schedule impact through the project’s normal customer coordination.'],['Customer requests a scope change.','PM and engineering prepare the quote on the OCR form.','Obtain written customer agreement; expect a separate customer PO.','Use a separate job number and accounting for the OCR.','Revise project dates when the change adds schedule days.'])
  ],
  takeaway:'Written agreement generally permits OCR work to proceed. Separate PO, job number and accounting preserve the original project budget.',
  scenario:{prompt:'The customer emails acceptance of an OCR adding a second product nest. The separate PO is still being processed. Engineering confirms the work adds three schedule days. What changes?',answer:'The written agreement is generally enough for TNi to proceed. Continue expecting the separate customer PO. Record the OCR under its separate job number and accounting, keep the original project budget unchanged, and revise affected project dates for the three added days.'},
  quiz:[q('o1','What triggers TNi’s OCR process?',['A customer scope-change request','Every supplier invoice','Every weekly status meeting','Any labor entry'],'Customer scope requests trigger the OCR process.'),q('o2','Who prepares the change quote?',['The PM working with engineering','The accountant alone','The customer’s trucking provider','The build team without the PM'],'The PM and engineering prepare the quote, issued on the OCR form.'),q('o3','What is generally sufficient to proceed before the separate PO arrives?',['Written customer agreement','An undocumented verbal comment','A supplier quotation alone','An internal assumption that the customer will agree'],'Written customer agreement is generally sufficient; a separate customer PO is still expected.'),q('o4','Where are OCR costs recorded?',['Under a separate job number and accounting','By increasing the original budget','In an untracked miscellaneous account','Only in the customer meeting minutes'],'Each OCR has separate job and accounting records.'),q('o5','When are project dates revised for the change?',['When it creates additional schedule days','For every OCR, regardless of impact','Only after warranty expires','Never, because the budget is separate'],'Separate accounting does not prevent schedule updates when the change adds days.'),
   q("o6","A department exceeds its planned hours without a new customer request. Does that alone establish an OCR?",["No; an internal overrun is not automatically a customer scope change", "Yes; every internal overrun must be billed as an OCR", "Yes; labor overruns always revise the customer’s scope", "No; it means the original cost plan can be discarded"],"The OCR trigger is a customer scope-change request. An internal overrun alone does not establish that trigger."),
   q("o7","Which document does TNi use to issue the change quotation?",["TNi’s OCR form, prepared by the PM with engineering", "A supplier order acknowledgement with no TNi quote", "The final acceptance form after shipment", "A verbal instruction with no written quotation"],"The PM and engineering define and quote the requested change using TNi’s OCR form."),
   q("o8","Written customer agreement allows the OCR work to proceed. What remains expected commercially?",["A separate customer PO for the OCR", "Cancellation of the separate PO requirement", "Charging all OCR work to the original project job number", "A replacement of the original project budget with the OCR price"],"Written agreement may allow work to begin, but TNi still expects a separate PO for the change."),
   q("o9","An approved OCR adds cost but no additional schedule days. What is the correct treatment?",["Use separate OCR accounting without automatically extending project dates", "Extend shipment by a standard number of days for every OCR", "Increase the original project budget and leave the OCR untracked", "Delay all original-scope work until warranty starts"],"Cost and schedule treatment are distinct: separate accounting is required, while dates change only when the work adds days."),
   q("o10","The customer verbally asks for extra work but has provided no written agreement. What should the PM obtain before relying on the proceed-before-PO practice?",["Written customer agreement to the quoted change", "Only an internal recollection of the phone call", "Only confirmation that engineering has available time", "Only a supplier’s promise to deliver the added parts"],"TNi’s practice generally permits proceeding on written customer agreement, not an undocumented verbal understanding.")]
 },
 {
  id:'recovery',title:'Recover a threatened milestone',phase:'Execute',subtitle:'Supplier follow-up and the operations escalation path',
  objectives:['Identify the PM’s supplier follow-up role.','Escalate a milestone risk to the right manager.','Use the agreed path for a revised ship date.'],
  foundation:'A risk threatens an outcome; an issue has already occurred. Both need attention when they endanger a milestone. Recovery planning identifies what can still be done to protect the commitment. Raising a risk early gives operations more options than reporting the missed date after it happens.',
  sections:[
   section('Stay close to purchased-item delivery',['The PM is responsible for supplier delivery follow-up. The purchasing agent occasionally assists with some purchased items. Ordering an item does not complete the PM’s schedule responsibility.','Use supplier delivery information against the activities depending on that item. In training practice, describe a delay in terms of the affected work and milestone so operations can assess it. These prompts help communicate the risk; they do not give the PM authority to approve departmental resource changes.']),
   section('Bring milestone jeopardy to operations',['If a milestone is in jeopardy, the PM addresses it with the operations manager. Operations reviews the situation and identifies the affected department, such as mechanical design. A recovery plan is then developed from that review.','The weekly internal status meeting provides a forum for schedule adherence, roadblocks and management intervention. It is not a reason to postpone raising a known milestone threat. Budget concerns normally follow the separate PM-to-general-manager path.']),
   section('Agree a revised delivery commitment internally',['If recovery cannot protect the promised shipment date, the operations manager reviews the revised date with the general manager for agreement. The agreed date then goes to the PM to communicate to the customer.','Customer-caused schedule impacts are discussed in customer meetings and added to open items. Use the recorded impact in the schedule discussion. Do not create an unapproved rule that every late customer response automatically produces the same number of extension days.'],['Identify the milestone at risk.','Raise it with the operations manager for assessment and recovery planning.','If shipment must move, operations obtains general-manager agreement.','The PM communicates the agreed revised date to the customer.'])
  ],
  takeaway:'PM → operations review and recovery → general-manager agreement if shipment must move → PM communication to the customer.',
  scenario:{prompt:'A purchased device slips two weeks and may delay build. The customer asks the PM to promise a new ship date immediately. What is the correct sequence?',answer:'Follow up with the supplier and bring the milestone risk to the operations manager. Operations assesses the affected work and the recovery plan. If the ship date must change, operations reviews it with the general manager for agreement; the PM then communicates the agreed date.'},
  quiz:[q('r1','Who owns supplier delivery follow-up?',['The PM, with occasional purchasing-agent assistance','Only the purchasing agent','Only the customer','Only the general manager'],'The PM retains the follow-up responsibility.'),q('r2','A milestone is in jeopardy. Who should the PM address?',['The operations manager','The trucking company first','Only the accountant','No one until the weekly meeting'],'The operations manager assesses the affected department and recovery needs.'),q('r3','Who reviews a revised ship date with the general manager?',['The operations manager','The supplier','The customer’s operator','The machine shop acting alone'],'Operations obtains general-manager agreement.'),q('r4','Who communicates the agreed revised date to the customer?',['The PM','The accountant','The outside rigger','The supplier without TNi involvement'],'The agreed date is passed to the PM for customer communication.'),q('r5','How should a customer-caused schedule impact be recorded?',['Discuss it in customer meetings and add it to open items','Treat every delay as an automatic extension','Omit it because TNi did not cause it','Wait until the final invoice'],'TNi discusses the impact and records it on the open-items list.'),
   q("r6","A supplier reports a likely delay before a milestone is missed. Why raise it now?",["Early escalation gives operations more recovery options", "Only missed milestones can be discussed with operations", "A likely delay automatically changes the promised date", "Ordering the item has already ended the PM’s responsibility"],"A risk needs attention while recovery options remain, rather than only after the date is missed."),
   q("r7","What information makes a supplier delay useful for operations to assess?",["The affected activities and the milestone they threaten", "Only the supplier’s name", "Only the item’s purchase price", "Only the date the original PO was issued"],"Connect supplier delivery information to the work and milestone that depend on it."),
   q("r8","What follows the PM’s escalation of milestone jeopardy to operations?",["Operations identifies the affected department and develops a recovery plan from the review", "The PM independently reallocates every department’s resources", "The customer automatically sets TNi’s recovery staffing", "The issue waits until the next invoicing milestone"],"Operations assesses the affected work and department so a recovery plan can be developed."),
   q("r9","A recovery review shows shipment must move. When should the PM communicate a revised commitment?",["After operations has obtained general-manager agreement on the revised date", "As soon as a supplier suggests any replacement date", "Before operations reviews the effect on other departments", "Only after the original ship date has already passed"],"The revised date follows internal agreement through operations and the GM before the PM communicates it to the customer."),
   q("r10","The customer provides information three days late. Should the PM automatically extend shipment by three days?",["No; discuss and record the actual schedule impact rather than assuming a day-for-day extension", "Yes; every late response automatically creates the same extension", "No; customer-caused delays must never appear on the schedule", "Yes; no internal assessment is needed for a customer delay"],"The process requires discussion and open-item recording of the impact, not an automatic extension rule.")]
 },
 {
  id:'testing',title:'Prove readiness at TNi',phase:'Deliver',subtitle:'Internal function testing and customer-witnessed runoff',
  objectives:['Identify the required internal testing scope.','Distinguish controls testing from PM readiness authority.','Record runoff approval and agreed completion items.'],
  foundation:'Verification means checking performance against requirements and retaining the results needed for decisions. A machine that runs is not necessarily ready for customer runoff. Safety interlocks, fault behavior, operator functions and cycle performance all belong in the readiness discussion. This lesson is a PM workflow lesson, not a machine-safety test procedure.',
  sections:[
   section('Test against the equipment requirements',['Internal testing covers function, confirmation of safety interlocks, PLC error-trapping effectiveness, HMI functions and troubleshooting. It then confirms target cycle time and all other technical requirements. A controls engineer is responsible for operating and testing the equipment and supplies the test results.','Use a requirement-specific view of readiness. For example, hitting the target cycle time does not establish that fault messages or interlocks function correctly. Unresolved issues need troubleshooting and evidence of the result.']),
   section('Make the readiness decision',['The PM determines readiness for customer runoff using the results from the controls engineer. The engineer’s operating and testing role and the PM’s readiness decision are related but distinct.','TNi plans to create an equipment-specific test checklist as a process improvement. It does not currently exist as the established tool described in this course. When created, the same checklist is intended for internal testing and repeat testing at the customer. This course does not claim to supply or replace that future equipment-specific checklist.']),
   section('Obtain customer-witnessed runoff approval',['The customer witnesses runoff at TNi and signs an approval form identifying any agreed items requiring completion. The signed form records the acceptance of that runoff and the remaining work.','TNi typically resolves the outstanding items before shipping. Some items may be completed at the customer site by agreement. Shipment with unresolved items is not an automatic entitlement; the agreed treatment matters. Internal runoff approval is also distinct from the final signed acceptance at the customer site.'])
  ],
  takeaway:'Controls provides test results; the PM determines readiness. Customer runoff produces a signed approval with agreed completion items.',
  scenario:{prompt:'The machine meets cycle time, but a fault condition is not reliably trapped by the PLC. The customer runoff is scheduled tomorrow. Is cycle-time performance enough to declare readiness?',answer:'No. PLC error trapping is part of the internal testing scope. The controls engineer needs to troubleshoot and test the issue, and the PM uses the testing results to determine readiness. The scheduled meeting and achieved cycle time do not establish that all technical requirements have been met.'},
  quiz:[q('t1','Who operates and tests the equipment and supplies internal results?',['The responsible controls engineer','The accountant','The shipping carrier','Only the customer'],'The controls engineer provides the operating and testing results.'),q('t2','Who determines readiness for customer runoff?',['The PM using the controls engineer’s results','The supplier without TNi review','The trucking company','Whoever first sees the machine cycle'],'The PM is responsible for the readiness decision.'),q('t3','Which is part of internal testing?',['Function, interlocks, PLC error trapping, HMI, troubleshooting, cycle time and other technical requirements','Cycle time only','Appearance only','Whether the final invoice is ready'],'All the listed technical areas are part of the review.'),q('t4','What is the status of the equipment-specific checklist?',['A planned process improvement to create later','An existing mandatory template supplied by this course','A substitute for engineering testing','Only a shipping document'],'The checklist is planned, not an existing established tool.'),q('t5','How are outstanding TNi runoff items handled?',['Normally before shipping; onsite completion may be agreed','Always postponed to the customer site','Ignored after signature','Automatically charged as an OCR'],'TNi normally resolves them before shipment, with some onsite exceptions by agreement.'),
   q("t6","A machine achieves the target cycle time, but PLC fault handling is unresolved. Is cycle time alone enough to establish readiness?",["No; fault behavior and the other technical requirements also need verification", "Yes; cycle time is the only readiness criterion", "Yes; unresolved controls issues can always be deferred without agreement", "No; the PM must personally rewrite the PLC before reviewing results"],"Readiness includes PLC error trapping and the full technical scope, not just cycle time."),
   q("t7","What records customer-witnessed runoff approval at TNi?",["A signed approval form identifying agreed items requiring completion", "Only a carrier’s collection receipt", "Only the PM’s statement that the machine runs", "The final customer-site acceptance document signed before installation"],"The TNi runoff approval form records that event and any agreed completion items."),
   q("t8","How is the future equipment-specific checklist intended to be used?",["For internal testing and repeat testing at the customer site once created", "Only to replace the customer’s purchase order", "Only to record transport charges", "As an already supplied checklist that replaces technical testing"],"The checklist is a planned improvement intended for both internal and onsite testing."),
   q("t9","A TNi runoff approval form lists an unresolved item proposed for onsite completion. What matters before shipment?",["Agreement on onsite completion; deferral is not automatic", "The signature alone authorizes every unresolved item to ship", "Removing the item from all follow-up records", "Treating the item as outside the original scope in every case"],"Outstanding items are normally resolved before shipment, with onsite completion permitted when agreed."),
   q("t10","What evidence should support the PM’s readiness decision after troubleshooting?",["The controls engineer’s test results against the equipment requirements", "Only a visual impression that the machine appears complete", "Only the booked date of the customer’s visit", "Only a confirmation that all purchased parts arrived"],"The PM determines readiness using the responsible controls engineer’s results against the technical requirements.")]
 },
 {
  id:'shipping',title:'Coordinate teardown and shipment',phase:'Deliver',subtitle:'Build ownership, outside resources and trucking arrangements',
  objectives:['Identify who coordinates teardown.','Apply the PM’s outside-resource responsibility.','Follow trucking arrangements established at PO.'],
  foundation:'A handoff changes who is doing the work but should preserve the project commitment. Teardown and transport need coordination with the condition accepted at runoff and with the work to be performed onsite. The PM’s role includes arranging the outside resources required by the project.',
  sections:[
   section('Move from runoff to teardown',['The build manager coordinates teardown at TNi. Keep the agreed runoff completion items in view as the machine is prepared to leave. Typically those items are resolved before shipping; any agreed onsite completion needs to remain visible for the next stage.','Do not assume a signed TNi runoff form means that final customer-site acceptance has occurred. The project still includes transport, reassembly, testing and final runoff.']),
   section('Arrange outside resources when required',['If teardown or shipment requires outside rigging or other resources, the PM arranges them. Coordinate those resources with the build manager’s teardown activities.','For a practice review, ask what outside resources are needed, when the machine will be ready for them and what dependencies could move that readiness. These are planning prompts, not new TNi approval authorities or a prescribed rigging method.']),
   section('Use the PO’s trucking arrangement',['Trucking is determined at the time of PO. Some customers have preferred logistics arrangements; otherwise the TNi PM arranges trucking. Review that arrangement before assuming which party is booking transportation.','The promised delivery date is shipment from TNi. The project schedule must also address the subsequent onsite work. Preserve the distinction so a trucking date is not represented as final acceptance.'],['Confirm the agreed treatment of outstanding runoff items.','Coordinate with the build manager on teardown.','Arrange outside rigging or other resources as required.','Apply the trucking arrangement established at PO.','Coordinate the transition to customer-site assembly and testing.'])
  ],
  takeaway:'Build coordinates teardown. The PM arranges required outside resources and trucking when the customer’s PO arrangement does not provide it.',
  scenario:{prompt:'A customer uses its preferred carrier, but TNi needs an outside rigger for teardown. Who handles each part?',answer:'The build manager coordinates teardown. The PM arranges the required outside rigger. Trucking follows the customer’s preferred logistics arrangement established at PO, with project coordination to align the activities.'},
  quiz:[q('s1','Who coordinates teardown?',['The build manager','The accountant','The customer’s operator','The controls supplier'],'The build manager coordinates teardown.'),q('s2','Who arranges required outside rigging or other resources?',['The PM','The customer automatically in every case','The accountant','No one until the truck arrives'],'The PM arranges required outside resources.'),q('s3','When is the trucking arrangement determined?',['At PO','Only after the truck arrives','After warranty expiration','At final invoice regardless of PO'],'Trucking arrangements are established at PO.'),q('s4','Who arranges trucking when there is no customer-provided logistics arrangement?',['The TNi PM','Always the machine shop','Always the OEM component supplier','The accountant'],'The TNi PM arranges trucking otherwise.'),q('s5','Does TNi runoff approval equal final customer-site acceptance?',['No; onsite reassembly, testing and final acceptance follow','Yes; warranty starts at TNi runoff in every case','Yes; no onsite tests are required','Only if the truck has been booked'],'The two approvals occur at different project stages.'),
   q("s6","A runoff item has been agreed for completion at the customer site. How should it be treated during teardown and shipment planning?",["Keep it visible through the handoff into onsite work", "Close it because teardown has begun", "Remove it from the record because runoff was signed", "Wait for the customer to report it again after installation"],"Agreed onsite completion items remain part of the project follow-up across the shipping handoff."),
   q("s7","The PM needs an outside rigger for teardown. What timing should be coordinated?",["The rigger’s availability with the build manager’s teardown readiness and dependencies", "Only the rigger’s earliest available date", "Only the original quote date", "The warranty end date instead of the teardown schedule"],"Outside resources must be coordinated with when the equipment and teardown activities will actually be ready."),
   q("s8","The PO establishes the customer’s preferred trucking arrangement. What should the PM do?",["Follow and coordinate that agreed arrangement", "Book a separate carrier without reviewing the arrangement", "Assume the build manager automatically books all trucking", "Treat trucking as unspecified despite the PO provision"],"Transportation planning follows the arrangement established at PO, including customer logistics preferences."),
   q("s9","Which event is the promised delivery milestone when coordinating the truck?",["Shipment from TNi", "Arrival at the customer’s receiving dock", "Completion of onsite reassembly", "Final signed customer-site acceptance"],"The promised delivery date is shipment from TNi; later onsite activities are separate project milestones."),
   q("s10","What work must remain visible in the plan after teardown and transport?",["Customer-site reassembly, testing and final runoff and acceptance", "Only the carrier’s delivery receipt", "Only payment collection, with technical work considered complete", "Only warranty claims, because installation is outside the project"],"TNi runoff and shipping do not end the project. Onsite reassembly, verification and acceptance still follow.")]
 },
 {
  id:'site',title:'Achieve customer-site acceptance',phase:'Deliver',subtitle:'Reassembly, repeat testing and customer-product runoff',
  objectives:['Coordinate onsite personnel and rigging.','Recognize the PM’s onsite role.','Identify the formal final-acceptance event.'],
  foundation:'Site acceptance demonstrates that the delivered and reassembled equipment performs to requirements in the customer setting. Repeat functional testing provides a basis for the customer-product runoff. A shipment or an installation start is not the final acceptance event.',
  sections:[
   section('Coordinate people and resources',['TNi determines the required internal and external personnel and rigging resources, and coordinates those needs with the customer. The PM is onsite during assembly and testing preparations for power-on and the replication of functional testing.','This lesson defines PM coordination responsibilities. Technical personnel determine and perform the applicable machine procedures; this course does not instruct the learner to energize equipment or conduct technical safety tests.']),
   section('Repeat function testing before product runoff',['Following reassembly, repeat the functional testing performed internally. The intended process improvement is to use the same equipment-specific checklist at TNi and onsite once that checklist has been created.','The technical scope includes equipment function, interlocks, PLC error trapping, HMI behavior, troubleshooting, cycle time and the other agreed technical requirements. Shipping and reassembly are reasons to verify performance again, not reasons to assume the earlier test result still demonstrates onsite performance.']),
   section('Obtain formal acceptance on the customer floor',['After successful repeat testing, runoff of customer product is conducted. When the equipment successfully meets requirements, the customer signs a formal acceptance document that lists any outstanding follow-up items.','That signed customer-floor acceptance starts the TNi warranty period. Retain the distinction between successful runoff, the signed acceptance document and the work remaining on the follow-up list. Closeout still requires completion of open items and delivery of the required documentation.'],['Coordinate onsite people and rigging with the customer.','Maintain the PM’s onsite involvement during assembly and testing.','Repeat functional testing.','Run customer product and demonstrate the requirements.','Obtain formal signed acceptance with outstanding follow-up items identified.'])
  ],
  takeaway:'Final acceptance is the customer’s formal signature on the customer floor after the equipment meets the required runoff conditions.',
  scenario:{prompt:'The machine has been reassembled onsite. The customer asks to sign acceptance immediately because it passed runoff at TNi. What sequence should the PM coordinate?',answer:'Coordinate repeat functional testing and then runoff of customer product. After successful completion to requirements, obtain the formal customer acceptance document, including any outstanding follow-up items. TNi’s earlier runoff signature is a different milestone.'},
  quiz:[q('a1','Who determines onsite personnel and rigging needs?',['TNi, coordinating with the customer','Only the trucking provider','Only the accountant','The customer without TNi involvement'],'TNi determines the internal and external resources and coordinates with the customer.'),q('a2','What is the PM’s onsite role?',['Be onsite during assembly and testing preparations','Attend only the final invoice meeting','Leave all coordination to the carrier','Approve tests without results'],'The PM is onsite through assembly and testing preparations.'),q('a3','What follows reassembly before customer-product runoff?',['Repeat functional testing','Immediate warranty expiration','Automatic final acceptance','Cancellation of all open items'],'Replicate function testing before the customer-product runoff.'),q('a4','What records final acceptance?',['The formal customer-signed acceptance document with follow-up items','The truck delivery receipt alone','The supplier’s packing slip','The original quotation alone'],'Final acceptance is formally signed on the customer floor.'),q('a5','When does the TNi warranty begin?',['At signed acceptance on the customer floor','At the quote date','At the supplier’s invoice date','At internal design kickoff'],'Signed customer-floor acceptance is the start event specified for the TNi warranty.'),
   q("a6","Why repeat functional testing after shipment and reassembly?",["Onsite performance must be verified again rather than assumed from earlier internal results", "Shipping automatically invalidates every engineering drawing", "Repeat testing is needed only if the truck arrived late", "Earlier results eliminate the need to check onsite performance"],"Transport and reassembly are reasons to verify that the equipment performs correctly in the customer setting."),
   q("a7","After successful repeat functional testing, what is the next acceptance step?",["Run customer product and demonstrate the agreed requirements", "Start the warranty without customer-product runoff", "Replace the acceptance document with the delivery receipt", "Close all open items automatically"],"Successful repeat testing provides the basis for customer-product runoff before formal acceptance."),
   q("a8","How should outstanding follow-up items be handled on the final acceptance document?",["Identify them and continue following them through completion", "Omit them because the signature means nothing can remain open", "Convert every item automatically into paid new scope", "Delay recording them until the warranty expires"],"Formal acceptance identifies outstanding follow-up work; the signature does not prove that work is already complete."),
   q("a9","Who performs the applicable technical procedures during onsite assembly and testing?",["The technical personnel, with the PM coordinating the project activities", "The PM alone because this course authorizes technical safety testing", "The trucking provider because it delivered the equipment", "Only the customer’s purchasing contact"],"This lesson defines PM coordination. Applicable equipment procedures are determined and performed by technical personnel."),
   q("a10","The equipment has arrived and installation has started, but no formal onsite acceptance is signed. What has not yet occurred?",["The final acceptance event that starts the TNi warranty", "The original PO acknowledgement", "The shipment milestone from TNi", "The initial decision to prepare a project plan"],"Delivery and installation start are not the final signed acceptance event on the customer floor.")]
 },
 {
  id:'closeout',title:'Finish the project deliberately',phase:'Sustain',subtitle:'Open items, documentation, training and invoicing',
  objectives:['Identify the closeout package.','Apply the training responsibilities in the quote and PO.','Distinguish PM invoice initiation from accounting execution.'],
  foundation:'Closeout turns an accepted machine into a completed handover. Follow-up items, operating information, drawings, training and financial milestones all need attention. A signature with outstanding items is not evidence that those items have been completed.',
  sections:[
   section('Complete the customer package',['The closeout package includes machine manuals; electrical, pneumatic, hydraulic and mechanical prints; recommended spare parts; and preventive maintenance schedules. These documents are created and provided to the customer as part of closeout.','The PM verifies that the package is complete and ensures that it reaches the customer. The PM’s verification responsibility does not mean the PM personally authors every technical document.']),
   section('Deliver the agreed training and follow-up',['TNi assembler and controls personnel provide training as required by the quotation and PO. Use those job-specific commitments to determine what training is required; do not invent a standard training duration or substitute the PM course for equipment instruction.','Complete all open items, including those listed on customer-site acceptance. Keep the distinction between the agreed future action and the action actually completed. Continue to monitor equipment issues during the provided warranty period.']),
   section('Initiate invoicing at the right milestones',['Payment milestones are included on the project plan. The PM is responsible for invoking the invoice process, while the TNi accountant executes that process. This applies throughout the project, not only at closeout.','At project closeout, initiate the final invoice for payment as applicable to the PO. The course does not define a new rule that final payment must already have been received before every closeout activity can finish. Use the agreed commercial terms.'],['Complete the open-item follow-up.','Verify the required documentation and deliver it to the customer.','Coordinate quotation/PO training with assembler and controls personnel.','Initiate the applicable final invoice with accounting.','Continue monitoring through the agreed warranty period.'])
  ],
  takeaway:'The PM owns completeness and delivery of the closeout package, and initiates invoicing; the accountant executes invoicing.',
  scenario:{prompt:'The machine is accepted, but preventive maintenance schedules are missing and a payment milestone has been reached. Who does what?',answer:'The PM ensures the missing maintenance information is completed and delivered with the closeout package. The PM also invokes the milestone invoice process; the TNi accountant executes it. Equipment training is supplied by assembler and controls personnel according to the quote and PO.'},
  quiz:[q('cl1','Which belongs in the closeout package?',['Manuals, technical prints, recommended spares and preventive maintenance schedules','Only a sales brochure','Only a truck receipt','Only a copy of this PM course'],'The package includes the specified operating and technical information.'),q('cl2','Who verifies the package is complete and reaches the customer?',['The PM','Only the trucking provider','Only the customer’s operator','The component supplier'],'The PM owns completeness and delivery.'),q('cl3','Who provides customer equipment training?',['TNi assembler and controls personnel as required by quote and PO','The accountant only','The PM alone for every subject','The carrier'],'Training is delivered by assembler and controls personnel according to the job commitments.'),q('cl4','Who initiates and who executes invoicing?',['PM initiates; TNi accountant executes','Accountant initiates; carrier executes','Customer operator initiates; PM executes all accounting','Build manager executes invoices without the PM'],'The PM invokes the process and accounting executes it.'),q('cl5','What happens to open items on the acceptance document?',['They are followed through to completion','They disappear when the customer signs','They are all automatically treated as new paid scope','They are always delayed until warranty ends'],'Signed acceptance can identify outstanding work; closeout includes completing it.'),
   q("cl6","The customer package contains mechanical prints but is missing required electrical and fluid-system prints. Is the package complete?",["No; include the electrical, pneumatic, hydraulic and mechanical prints required in the closeout package", "Yes; mechanical prints replace all other disciplines", "Yes; missing prints can always wait until warranty expiration", "No; the PM must personally redraw every print"],"The closeout package includes technical prints across the listed disciplines, with the PM verifying completeness and delivery."),
   q("cl7","How should the scope of customer equipment training be established?",["Use the training commitments in the quotation and PO", "Apply a universal duration invented for every job", "Replace equipment training with this PM course", "Let the shipping date eliminate the training obligation"],"Assembler and controls personnel provide the training required by the job’s quote and PO."),
   q("cl8","A payment milestone is reached before project closeout. What should the PM do?",["Initiate the invoice process with accounting at that milestone", "Wait until closeout to initiate every invoice", "Assume the customer will create TNi’s invoice", "Remove the milestone because the project is still active"],"The PM initiates milestone invoicing throughout the project, while the TNi accountant executes it."),
   q("cl9","Does the PM’s responsibility to verify the closeout package mean the PM authors every technical document?",["No; the PM ensures completeness and delivery while the appropriate personnel prepare the documents", "Yes; only the PM may create technical prints", "No; it means no one must check the package", "Yes; engineering documents are excluded from the package"],"Verification and delivery responsibility are distinct from personally creating every technical document."),
   q("cl10","The acceptance form is signed, but one agreed follow-up item remains unfinished. What is the correct closeout treatment?",["Continue tracking the item to completion while completing the other closeout obligations", "Treat the signature as proof that the item is complete", "Delete the item when the final invoice is initiated", "Assume it automatically becomes an ordinary warranty claim"],"Signed acceptance with an outstanding action does not establish completion of that action. Closeout includes follow-through.")]
 },
 {
  id:'warranty',title:'Support the warranty period',phase:'Sustain',subtitle:'Job-specific terms, OEM coverage and workmanship evaluation',
  objectives:['Use the job’s PO warranty terms and start event.','Distinguish OEM component coverage from workmanship coverage.','Apply TNi’s evaluation process to reported failures.'],
  foundation:'Warranty coverage depends on the agreement and the cause of a failure. Component coverage and workmanship coverage can have different durations. This lesson describes the TNi practice provided for the course; it does not replace the job’s agreed terms or resolve an individual claim without examination.',
  sections:[
   section('Start from the PO and signed onsite acceptance',['Warranty duration and terms are specified individually at PO. The TNi warranty begins at signed acceptance on the customer floor. There is no universal two-year warranty for every TNi job.','At closeout, preserve the acceptance event and the applicable job terms so reported issues can be evaluated against the correct period and scope of coverage. Monitoring continues during the warranty period TNi provided.']),
   section('Separate ordinary component failure from workmanship',['TNi typically uses OEM component warranty coverage even when the customer requires a longer period for TNi workmanship. The longer workmanship period does not automatically extend ordinary component replacement coverage.','Example from the agreed process: a purchased component may have one year of OEM coverage while TNi provides two years for workmanship. An ordinary component failure after that one-year coverage is not automatically replaced merely because the two-year workmanship period continues. Check the applicable terms rather than assuming every OEM clock is identical.']),
   section('Evaluate cause before deciding coverage',['TNi typically covers the situation during the workmanship warranty if TNi workmanship clearly led directly to the component failure, even if the component’s OEM warranty has expired. The causal connection matters.','TNi examines the situation. Customer maintenance resources may participate in some cases, but TNi reserves the right to make the determination. The course does not assign that authority to a particular individual who has not been identified in the established process.'],['Confirm the job-specific warranty terms and acceptance record.','Gather the reported issue for TNi examination.','Distinguish component coverage from a possible workmanship cause.','Include customer maintenance resources when appropriate.','Use TNi’s determination to establish the response.'])
  ],
  takeaway:'Longer workmanship coverage does not automatically extend OEM component coverage. TNi examines the cause and retains the determination.',
  scenario:{prompt:'The job has two years of workmanship coverage and one year of OEM component coverage. A component fails after the OEM period. Examination clearly links the failure directly to TNi workmanship. How is this different from ordinary component failure?',answer:'An ordinary component failure would not automatically be covered merely because the workmanship period is longer. A failure clearly caused directly by TNi workmanship would typically be covered during the applicable workmanship period. TNi examines the situation and makes the determination.'},
  quiz:[q('w1','Where are warranty duration and terms specified?',['Individually at PO','By one universal two-year rule','By the trucking provider','By this course replacing the PO'],'Warranty terms are job-specific at PO.'),q('w2','What starts the TNi warranty period?',['Signed acceptance on the customer floor','The PO acknowledgement','The first design review','The date the machine leaves the supplier'],'Signed final acceptance on the customer floor starts the period.'),q('w3','Does a longer workmanship warranty automatically extend OEM coverage?',['No','Yes, for all components','Yes, if the PM has closed the invoice','Only if the truck arrived on time'],'OEM and workmanship coverage can have different durations.'),q('w4','When may TNi cover a component failure after OEM coverage expires?',['When TNi workmanship clearly caused it directly and applicable workmanship coverage remains','Whenever the customer prefers replacement','Whenever the component was expensive','Never under any circumstances'],'A clear direct workmanship cause can bring the failure under the applicable workmanship coverage.'),q('w5','Who retains the right to make the warranty determination?',['TNi after examination, sometimes involving customer maintenance','The carrier','The supplier’s salesperson alone','Any course participant automatically'],'TNi examines the situation and retains the determination.'),
   q("w6","What records should support the initial review of a reported warranty issue?",["The job’s PO warranty terms and signed customer-site acceptance record", "Only the supplier’s sales brochure", "Only the machine’s shipment date", "A standard two-year assumption for every job"],"Job-specific terms and the acceptance event establish the relevant period and scope of the TNi warranty."),
   q("w7","A component has one year of OEM coverage and TNi workmanship coverage continues for two years. An ordinary component failure occurs after the OEM year, with no workmanship cause established. What should be assumed?",["Replacement is not automatic merely because workmanship coverage continues; examine the applicable terms and cause", "Every component automatically has two years of coverage", "The failure must be caused by workmanship because it occurred later", "The OEM warranty restarts whenever a service call is made"],"Longer workmanship coverage does not automatically extend ordinary OEM component replacement coverage."),
   q("w8","What finding matters when considering workmanship coverage for a failed component after OEM coverage expires?",["Evidence that TNi workmanship clearly and directly caused the failure within applicable workmanship coverage", "Only that the component was expensive", "Only that the customer prefers a free replacement", "Only that the OEM warranty has expired"],"The direct causal connection to TNi workmanship is central to evaluating this coverage situation."),
   q("w9","What role may customer maintenance play in a warranty examination?",["Participate where appropriate while TNi retains the determination", "Automatically replace TNi as the final decision authority", "Set new warranty terms after each failure", "Approve coverage solely from the component’s purchase price"],"Customer maintenance may assist in examining the situation, but TNi reserves the right to determine the response."),
   q("w10","Does this training course resolve an individual warranty claim without examination?",["No; apply the job’s agreed terms and examine the reported failure", "Yes; every reported component failure is covered", "Yes; every failure after OEM expiration must be rejected", "No; only the customer’s preferred outcome is relevant"],"The lesson describes TNi practice. Individual claims still require examination of the cause and applicable job terms.")]
 },
];

