export const glossary=[
 ['PO','Purchase order. The customer’s order establishes job-specific commercial commitments.'],
 ['OCR','Order Change Request. TNi’s process for quoting and authorizing customer scope changes.'],
 ['Scope of supply','The equipment, work and deliverables TNi has agreed to provide.'],
 ['Cost detail','The estimate of labor, material, purchased items and outside work used to target the project budget.'],
 ['Milestone','A significant project event, such as design approval, shipment or payment.'],
 ['Dependency','Work or a decision needed before another activity can proceed.'],
 ['Actual vs. plan','Comparison of recorded costs and labor with the corresponding cost-detail allowances.'],
 ['Commitment','An obligation such as an open PO that may not yet appear as a posted actual cost.'],
 ['Runoff','Demonstration of equipment performance against requirements, first at TNi and then at the customer site.'],
 ['PLC / HMI','Programmable logic controller / human-machine interface. Controls logic and the operator interface.'],
 ['OEM','Original equipment manufacturer. Purchased components may have OEM coverage different from TNi workmanship coverage.'],
 ['Contact hours','Active lesson and assessment time, including retakes. This course does not award external certification credit.']
];
